={
  "statement": "MATCH (r:Recipe) OPTIONAL MATCH (r)-[:CONTAINS]->(i:Ingredient) OPTIONAL MATCH (r)-[:BELONGS_TO]->(c:Category) WITH r, collect(DISTINCT i.name) AS ingredients, collect(DISTINCT c.name) AS categories WHERE ($ingredient IS NULL OR $ingredient IN ingredients) AND ($category IS NULL OR $category IN categories) RETURN r.name AS recipe, ingredients, categories",
  "parameters": {
    "ingredient": {{ $json.ingredient ? JSON.stringify($json.ingredient) : 'null' }},
    "category": {{ $json.category ? JSON.stringify($json.category) : 'null' }}
  }
}
